package tools

import "github.com/panjie/mods/internal/prompts"

const ToolSelectionRules = prompts.ToolSelection

const PosixShellRunDescription = "Run a command that requires POSIX shell syntax and return stdout+stderr. Prefer process_run for one executable, including git, tests, builds, package managers, and installers. Use this tool for necessary pipelines, redirection, variable expansion, globbing, or shell builtins. The command string is already executed through the POSIX shell; pass the shell source directly and do not wrap it in sh -c, bash -c, or another nested shell host. " + prompts.POSIXIntentGuidance + " Commands already run with the current working directory as their process cwd; use the cwd argument instead of prepending cd. Output is returned directly; do not redirect to a file just to see results. " + prompts.ScriptPolicy + " " + CommandEffectGuidance

const WindowsShellRunDescription = "Run a PowerShell command via the available PowerShell host (pwsh.exe if present, otherwise powershell.exe) with -NoProfile -NonInteractive -ExecutionPolicy Bypass -Command and return stdout+stderr. Commands already run with the current working directory as their process cwd; use the cwd argument instead of prepending Set-Location, cd, or Push-Location. Prefer powershell_run for Windows shell work; shell_run is a compatibility alias with the same PowerShell command syntax. Use native PowerShell cmdlets and pipelines such as Get-ChildItem, Select-String, Where-Object, Test-Path, Get-Content, and Measure-Object instead of POSIX-only utilities unless intentionally invoking an installed external program. " + prompts.PowerShellIntentGuidance + " Output is returned directly; do not use Out-File, Set-Content, or shell redirection just to see results. " + prompts.ScriptPolicy + " " + CommandEffectGuidance

const PowerShellRunDescription = "Run a PowerShell command directly via the available PowerShell host (pwsh.exe if present, otherwise powershell.exe) with -NoProfile -NonInteractive -ExecutionPolicy Bypass -Command and return stdout+stderr. Pass only the PowerShell pipeline or script block; do not prefix with powershell, powershell.exe, pwsh, or -Command. Commands already run with the current working directory as their process cwd; use the cwd argument instead of prepending Set-Location, cd, or Push-Location. Use native PowerShell cmdlets and pipelines such as Get-ChildItem, Select-String, Where-Object, Test-Path, Get-Content, and Measure-Object instead of POSIX-only utilities unless intentionally invoking an installed external program. " + prompts.PowerShellIntentGuidance + " Output is returned directly; do not use Out-File, Set-Content, or shell redirection just to see results. " + prompts.ScriptPolicy + " " + CommandEffectGuidance

const ProcessRunDescription = "Run one native executable with literal argv. Return JSON with exit_code, stdout/stderr, duration, timeout and truncation metadata. Prefer this tool for single executables (git, builds, tests, installers); program names the executable, not a shell wrapper. Use shell_run/powershell_run for shell source; invoke script files by interpreter and path. Windows .bat/.cmd require powershell_run. On POSIX, invoke sudo directly for secure askpass. cwd defaults to the current working directory. " + prompts.ScriptPolicy + " " + CommandEffectGuidance

const RuntimeInfoDescription = "Report the current OS, architecture, cwd, and the exact shell host selected by mods. Optionally resolve up to 20 bare command names on PATH without executing them. Use only when platform or command availability is relevant and not already known."

// CommandEffectGuidance is included in every command tool in normal and minimal modes.
const CommandEffectGuidance = "Declare effect for the entire call, including pipelines, subprocesses and scripts. Use read_only only for reads or computation without expected persistent changes. Use may_write for writes, installs, build artifacts, messages, remote changes or uncertainty. Mixed reads/writes are may_write. Perform necessary changes normally; never mislabel a call to avoid approval. mods trusts this declaration: read_only runs directly; may_write requests approval unless review is disabled."
